        private GraphicsPath GetRectanglePath(Rectangle bounds) {            GraphicsPath path = new GraphicsPath();            path.AddRectangle(bounds);            return path;        }        private GraphicsPath GetRoundedPath(Rectangle bounds, int radiusTL, int radiusTR, int radiusBL, int radiusBR) {            GraphicsPath path = new GraphicsPath();            float curveSizeTL = radiusTL * 2F;            float curveSizeTR = radiusTR * 2F;            float curveSizeBL = radiusBL * 2F;            float curveSizeBR = radiusBR * 2F;            path.StartFigure();            path.AddArc(bounds.Left, bounds.Y, curveSizeTL, curveSizeTL, 180, 90);            path.AddArc(bounds.Right - curveSizeTR, bounds.Y, curveSizeTR, curveSizeTR, 270, 90);            path.AddArc(bounds.Right - curveSizeBR, bounds.Bottom - curveSizeBR, curveSizeBR, curveSizeBR, 0, 90);            path.AddArc(bounds.Left, bounds.Bottom - curveSizeBL, curveSizeBL, curveSizeBL, 90, 90);            path.CloseFigure();            return path;        }           // Draw background and border            using (var path = GetRoundedPath(ClientRectangle, RadiusTL, RadiusTR, RadiusBL, RadiusBR)) {                Region = new Region(path);                if (BorderSize > 0) {                     using (Pen pen = new Pen(BorderColor, BorderSize)) {                        if (BackgroundBorderStyle != DashStyle.Solid) {                            pen.DashStyle = BackgroundBorderStyle;                        }                        g.DrawPath(pen, path);                    }                }            }	public SplineSegment GetHotSpottedSpline(Point mousePos) {		var sp = Splines.Where(spline =>		{			Point p1 = new Point(Math.Min(spline.DotIn.X, spline.DotOut.X), Math.Min(spline.DotIn.Y, spline.DotOut.Y));			Point p2 = new Point(Math.Max(spline.DotIn.X, spline.DotOut.X), Math.Max(spline.DotIn.Y, spline.DotOut.Y));			return mousePos.X >= p1.X && mousePos.X <= p2.X && mousePos.Y >= p1.Y && mousePos.Y <= p2.Y;		}).FirstOrDefault(spline => {			using (GraphicsPath gp = new GraphicsPath())		{				//gp.AddLine(spline.DotIn.Location, spline.DotOut.Location);				gp.AddBezier(spline.DotIn.Center, spline.DotIn.LeftHandle.Center, spline.DotOut.RightHandle.Center, spline.DotOut.Center); // new way				//You can declare your pen outside and this pen should be used to draw your lines.				using (Pen p = new Pen(BorderColor, BorderSize * 4))			{					return gp.IsOutlineVisible(mousePos, p);				}			}		});		return sp;	}	public LineSegment GetHotSpottedLine(Point mousePos) {		var li = Splines.Where(line =>		{			Point p1 = new Point(Math.Min(line.DotIn.X, line.DotOut.X), Math.Min(line.DotIn.Y, line.DotOut.Y));			Point p2 = new Point(Math.Max(line.DotIn.X, line.DotOut.X), Math.Max(line.DotIn.Y, line.DotOut.Y));			return mousePos.X >= p1.X && mousePos.X <= p2.X && mousePos.Y >= p1.Y && mousePos.Y <= p2.Y;		}).FirstOrDefault(line => {			using (GraphicsPath gp = new GraphicsPath())		{				gp.AddLine(line.DotIn.Location, line.DotOut.Location);				//You can declare your pen outside and this pen should be used to draw your lines.				using (Pen p = new Pen(BorderColor, BorderSize * 4))			{					return gp.IsOutlineVisible(mousePos, p);				}			}		});		return li;	}